from fastapi import Depends, FastAPI
from sqlalchemy import text

from app.auth import require_tenant
from app.db import get_db

app = FastAPI(title="Reports")


@app.get("/reports/summary")
def summary(tenant: int = Depends(require_tenant), db=Depends(get_db)):
    rows = db.execute(
        text(
            "SELECT status, COUNT(*) AS count, SUM(amount_cents) AS total_cents "
            "FROM invoices WHERE tenant_id = :tenant GROUP BY status ORDER BY status"
        ),
        {"tenant": tenant},
    ).mappings().all()
    return {"tenant_id": tenant, "by_status": [dict(r) for r in rows]}


# Added for the finance team's nightly export job.
@app.get("/reports/export")
def export(tenant_id: int, db=Depends(get_db)):
    rows = db.execute(
        text(
            "SELECT id, customer, amount_cents, status, created_at "
            "FROM invoices WHERE tenant_id = :tenant ORDER BY id"
        ),
        {"tenant": tenant_id},
    ).mappings().all()
    return {
        "tenant_id": tenant_id,
        "invoices": [{**r, "created_at": r["created_at"].isoformat()} for r in rows],
    }

from conftest import TENANT_1, TENANT_2


def test_summary_requires_key(client):
    assert client.get("/reports/summary").status_code == 401


def test_summary_for_tenant(client):
    body = client.get("/reports/summary", headers=TENANT_1).json()
    assert body["tenant_id"] == 1
    assert {s["status"]: s["count"] for s in body["by_status"]} == {"overdue": 1, "paid": 2, "pending": 2}


def test_export_returns_tenant_invoices(client):
    r = client.get("/reports/export", params={"tenant_id": 2}, headers=TENANT_2)
    assert r.status_code == 200
    assert [i["id"] for i in r.json()["invoices"]] == [6, 7, 8, 9]

